// State shape: { status: "loading" } | { status: "error", message }
//   | { status: "success", data: Course[] }.
export function CourseCatalog({ result, onRetry }) {
  switch (result.status) {
    case "loading":
      return <p role="status" aria-busy="true">Loading courses...</p>;
    case "error":
      return (
        <div role="alert">
          <p>Couldn't load courses. {result.message}</p>
          <button type="button" onClick={onRetry}>Try again</button>
        </div>
      );
    case "success":
      if (result.data.length === 0) return <p>No courses yet. New ones are added every month.</p>;
      return (
        <ul>{result.data.map((c) => <li key={c.id}>{c.title}</li>)}</ul>
      );
    default:
      return null;
  }
}
```

| Status | Screen |
|---|---|
| loading. | skeleton or message with aria-busy. |
| error. | alert text plus Try again. |
| success, 0 items. | a helpful empty message. |
| success, items. | the list. |
| stale (refreshing). | old list plus a small "updating" note. |

